#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> K(n);
    vector<vector<pair<int,int>>> cells(n);
    int totalCells = 0;
    for(int i=0;i<n;i++){
        cin >> K[i];
        cells[i].resize(K[i]);
        for(int j=0;j<K[i];j++) cin >> cells[i][j].first >> cells[i][j].second;
        totalCells += K[i];
    }

    // Transform: first flip (f=1 means x -> -x), then rotate r times 90° CCW
    // CCW rotation: (x,y) -> (-y, x)
    auto getTransformed = [](const vector<pair<int,int>>& src, int r, int f) -> vector<pair<int,int>> {
        vector<pair<int,int>> dst(src.size());
        for(int i=0;i<(int)src.size();i++){
            int x = src[i].first, y = src[i].second;
            if(f) x = -x;
            for(int q=0;q<r;q++){ int t=x; x=-y; y=t; }
            dst[i] = {x,y};
        }
        int mx=INT_MAX, my=INT_MAX;
        for(auto&[x,y]:dst){ mx=min(mx,x); my=min(my,y); }
        for(auto&[x,y]:dst){ x-=mx; y-=my; }
        return dst;
    };

    vector<int> order(n);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int a, int b){ return K[a]>K[b]; });

    int side = max(10, (int)ceil(sqrt(totalCells * 1.5)));
    int W = side, H = side;

    vector<vector<bool>> grid(W, vector<bool>(H, false));
    vector<int> heightmap(W, 0);
    vector<int> ox(n), oy(n), orr(n), of(n);

    for(int idx=0;idx<n;idx++){
        int pi = order[idx];
        int bestScore = INT_MAX, bx=-1, by=-1, br=0, bf=0;

        for(int f=0;f<2;f++){
            for(int r=0;r<4;r++){
                auto tc = getTransformed(cells[pi], r, f);
                int tw=0, th=0;
                for(auto&[x,y]:tc){ tw=max(tw,x+1); th=max(th,y+1); }
                if(tw > W || th > H) continue;

                for(int x=0; x<=W-tw; x++){
                    int minY=0;
                    for(auto&[cx,cy]:tc){
                        minY = max(minY, heightmap[x+cx] - cy);
                    }
                    if(minY+th > H) continue;
                    // check no overlap
                    bool ok=true;
                    for(auto&[cx,cy]:tc){
                        if(grid[x+cx][minY+cy]){ok=false;break;}
                    }
                    if(!ok) continue;
                    int topY=0;
                    for(auto&[cx,cy]:tc) topY=max(topY, minY+cy+1);
                    if(topY < bestScore){
                        bestScore=topY; bx=x; by=minY; br=r; bf=f;
                    }
                }
            }
        }

        if(bx==-1){ bx=0; by=*max_element(heightmap.begin(),heightmap.end()); br=0; bf=0; }

        auto tc = getTransformed(cells[pi], br, bf);
        for(auto&[cx,cy]:tc){
            int gx=bx+cx, gy=by+cy;
            if(gx<W && gy<H) grid[gx][gy]=true;
            heightmap[bx+cx] = max(heightmap[bx+cx], by+cy+1);
        }
        ox[pi]=bx; oy[pi]=by; orr[pi]=br; of[pi]=bf;
    }

    int maxH=0;
    for(int i=0;i<W;i++) maxH=max(maxH,heightmap[i]);

    cout << W << " " << maxH << "\n";
    for(int i=0;i<n;i++){
        cout << ox[i] << " " << oy[i] << " " << orr[i] << " " << of[i] << "\n";
    }

    return 0;
}
